import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"Capacity","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/storage/capacity.md","filePath":"en/modules/storage/capacity.md","lastUpdated":0}`),a={name:`en/modules/storage/capacity.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="capacity" tabindex="-1">Capacity <a class="header-anchor" href="#capacity" aria-label="Permalink to “Capacity”">​</a></h1><p>This page covers EmakiStorage&#39;s capacity domain model: the <code>capacity</code> section of <code>config.yml</code>, the four capacity sources, the three-level <code>stackLimit</code>, and what happens to occupancy when capacity shrinks.</p><h2 id="capacity-1" tabindex="-1">capacity <a class="header-anchor" href="#capacity-1" aria-label="Permalink to “capacity”">​</a></h2><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">capacity</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  base_slots</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">45</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  max_slots</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1000</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  warn_entry_count</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5000</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  default_stack_limit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>base_slots</code></td><td>int</td><td><code>45</code></td><td>Default open slot count (45 = 5 × 9, matching the <code>gui.storage_rows</code> default).</td></tr><tr><td><code>max_slots</code></td><td>int</td><td><code>1000</code></td><td>Hard ceiling on total slots. <code>0</code> means unlimited.</td></tr><tr><td><code>warn_entry_count</code></td><td>int</td><td><code>5000</code></td><td>Logs a console warning when the entry count exceeds this value. <code>0</code> disables the warning.</td></tr><tr><td><code>default_stack_limit</code></td><td>long</td><td><code>100</code></td><td>Config-level per-slot ceiling. At this level <code>0</code> means unlimited.</td></tr></tbody></table><h3 id="four-capacity-sources" tabindex="-1">Four Capacity Sources <a class="header-anchor" href="#four-capacity-sources" aria-label="Permalink to “Four Capacity Sources”">​</a></h3><p><code>effectiveSlots</code> is the sum of four independently persisted sources, then clamped:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>effective = clamp(base_slots + permission tier + grantedSlots + purchasedSlots, 0, max_slots)</span></span></code></pre></div><p>The upper clamp is skipped when <code>max_slots</code> is <code>0</code>. Because the four sources are stored separately, lowering <code>base_slots</code> never consumes slots a player was granted or purchased.</p><table tabindex="0"><thead><tr><th>Source</th><th>Comes from</th><th>Can be negative</th></tr></thead><tbody><tr><td><code>baseSlots</code></td><td><code>capacity.base_slots</code></td><td>No (negatives treated as 0)</td></tr><tr><td><code>permissionSlots</code></td><td>Highest <code>emakistorage.slots.&lt;n&gt;</code> tier</td><td>No</td></tr><tr><td><code>grantedSlots</code></td><td><code>/estorage slot grant</code>, API <code>grantSlotsAsync</code>, action <code>storage_grant_slot</code></td><td>Yes</td></tr><tr><td><code>purchasedSlots</code></td><td>In-GUI paid expansion, action <code>storage_unlock_slot</code></td><td>No</td></tr></tbody></table><p>Page count is derived from slot count and cannot be configured in reverse:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>totalPages     = max(1, ceil(effectiveSlots / slots per page))</span></span>
<span class="line"><span>reachablePages = max(1, ceil(usedSlots / slots per page))</span></span></code></pre></div><p>Page 1 is always reachable (an empty warehouse must still open and accept its first item); a page holding no entry at all cannot be paged into.</p><p>Confirm you have enough memory before setting <code>max_slots</code> to <code>0</code> (unlimited). The figure given in the config comment is roughly 100–200MB of heap for 100,000 entries on one player; that is an estimate and has not been measured.</p><h2 id="three-level-stacklimit" tabindex="-1">Three-Level stackLimit <a class="header-anchor" href="#three-level-stacklimit" aria-label="Permalink to “Three-Level stackLimit”">​</a></h2><p>The per-slot ceiling resolves most-specific-first across three levels:</p><table tabindex="0"><thead><tr><th>Level</th><th>Stored in</th><th>Set through</th><th>Meaning of <code>0</code></th></tr></thead><tbody><tr><td>Entry</td><td>The matching entry in <code>meta.yml</code></td><td><code>/estorage stacklimit slot</code>, API <code>setSlotStackLimitAsync</code>, action <code>storage_set_stacklimit</code> with <code>slot</code></td><td>Inherit the player level</td></tr><tr><td>Player</td><td><code>defaultStackLimit</code> in <code>meta.yml</code></td><td><code>/estorage stacklimit player</code>, API <code>setStackLimitAsync</code>, action <code>storage_set_stacklimit</code> without <code>slot</code></td><td>Inherit the config level</td></tr><tr><td>Config</td><td><code>capacity.default_stack_limit</code> in <code>config.yml</code></td><td>Config file</td><td><strong>Unlimited</strong> (equivalent to <code>Long.MAX_VALUE</code>)</td></tr></tbody></table><p>The same <code>0</code> means different things per level: at entry and player level it means &quot;inherit the next level&quot;, at config level it means &quot;no limit&quot;. Resolution order is entry level <code>&gt; 0</code>, then player level <code>&gt; 0</code>, then the config level; a config level <code>&lt;= 0</code> yields <code>Long.MAX_VALUE</code>.</p><p>The <code>emakistorage.stacklimit.&lt;n&gt;</code> permission tier can also supply a player-level ceiling, again taking the highest value and not supporting wildcards.</p><h2 id="one-item-across-several-slots" tabindex="-1">One Item Across Several Slots <a class="header-anchor" href="#one-item-across-several-slots" aria-label="Permalink to “One Item Across Several Slots”">​</a></h2><p>By default a full slot refuses the remainder. With <code>behavior.multi_slot_stacking</code> set to <code>true</code>, one item type may occupy further slots and keep storing.</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">behavior</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  multi_slot_stacking</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"> # true = one entry may span several slots</span></span></code></pre></div><p>With a per-slot ceiling of 100 and 120 oak logs in hand:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Result</th></tr></thead><tbody><tr><td><code>false</code> (default)</td><td>100 stored, the remaining 20 refused (<code>slot_full</code>)</td></tr><tr><td><code>true</code></td><td>120 stored, displayed as the two slots <code>[100]</code> <code>[20]</code></td></tr></tbody></table><h3 id="how-the-occupied-span-is-derived" tabindex="-1">How the Occupied Span Is Derived <a class="header-anchor" href="#how-the-occupied-span-is-derived" aria-label="Permalink to “How the Occupied Span Is Derived”">​</a></h3><p>The occupied span is not persisted; it is derived from the amount on every read:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>span      = ceil(entry amount / per-slot ceiling)</span></span>
<span class="line"><span>usedSlots = sum of every entry&#39;s span</span></span></code></pre></div><p><code>usedSlots</code> has to count spans, otherwise a player could fill 90 slots with 45 spanning entries while only being charged 45, walking straight past <code>max_slots</code>.</p><p>When the per-slot ceiling is unlimited (<code>default_stack_limit: 0</code> with no player- or entry-level override) <code>span</code> is always <code>1</code>: a percentage of unlimited is meaningless, so there is no remainder to spill into a second slot.</p><h3 id="withdrawal-and-merging" tabindex="-1">Withdrawal and Merging <a class="header-anchor" href="#withdrawal-and-merging" aria-label="Permalink to “Withdrawal and Merging”">​</a></h3><p>The slots of a spanning entry <strong>share one amount pool</strong>, so clicking any of them debits the entry total. Because span is derived, shrinking is automatic and there is no &quot;merge&quot; step:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>120 units (ceiling 100)  →  [100] [20]      2 slots occupied</span></span>
<span class="line"><span>withdraw 20 from slot 1  →  [100]           1 slot occupied, later entries roll forward</span></span></code></pre></div><p>Entries themselves live in a gap-free compact list, so &quot;later items roll forward&quot; is the list&#39;s natural state and the window re-derives it on every repaint.</p><h3 id="display" tabindex="-1">Display <a class="header-anchor" href="#display" aria-label="Permalink to “Display”">​</a></h3><p>Each slot shows <strong>its own amount</strong> rather than the entry total (slot 1 <code>100/100</code>, slot 2 <code>20/100</code>), matching how players read a vanilla container. A spanning entry appends one extra <code>gui.entry.span_total</code> line stating the entry total and how many slots it occupies.</p><h3 id="interaction-with-other-mechanisms" tabindex="-1">Interaction With Other Mechanisms <a class="header-anchor" href="#interaction-with-other-mechanisms" aria-label="Permalink to “Interaction With Other Mechanisms”">​</a></h3><table tabindex="0"><thead><tr><th>Surface</th><th>Behaviour</th></tr></thead><tbody><tr><td>Total slot limit</td><td>Still enforced. Whatever does not fit is refused as before and never exceeds <code>capacity.max_slots</code>.</td></tr><tr><td><code>%used_slots%</code> (placeholder, <code>/estorage info</code>, the window&#39;s capacity line)</td><td>Follows the new semantics automatically: once enabled it reports <strong>occupied slots</strong> rather than entry count.</td></tr><tr><td><code>/estorage stacklimit slot &lt;n&gt;</code>, API <code>setSlotStackLimitAsync</code>, <code>StorageEntrySnapshot.slotIndex</code></td><td>Still the <strong>entry index</strong>, not the displayed slot number. The ceiling belongs to the entry, and the entry index is the stable identity. With the setting off the two coincide.</td></tr><tr><td>Search hit count <code>%visible%</code></td><td>Still the number of matching <strong>entries</strong>, because players search for items rather than slots.</td></tr><tr><td>Overflow locking</td><td>Accumulates the boundary by span. An entry crossing the capacity boundary is locked as a whole (read-only, withdrawable), preserving zero loss.</td></tr><tr><td>Persistence</td><td>Format unchanged. Spanning only makes the entry amount larger, and the amount was already a variable-length integer.</td></tr></tbody></table><h3 id="after-turning-it-back-off" tabindex="-1">After Turning It Back Off <a class="header-anchor" href="#after-turning-it-back-off" aria-label="Permalink to “After Turning It Back Off”">​</a></h3><p>Going from <code>true</code> back to <code>false</code> loses no data: entries already above the per-slot ceiling still occupy one slot, display truncated at 100%, refuse new deposits and can be emptied normally.</p><h3 id="cost" tabindex="-1">Cost <a class="header-anchor" href="#cost" aria-label="Permalink to “Cost”">​</a></h3><p>With the setting off, <code>usedSlots</code> is O(1) (the entry count directly). Once on, every entry must be walked to accumulate spans, so the per-repaint cost rises for players with very many entries. Capacity is resolved once per repaint rather than once per slot, but the walk itself is unavoidable.</p><h2 id="shrinking-and-overflow" tabindex="-1">Shrinking and Overflow <a class="header-anchor" href="#shrinking-and-overflow" aria-label="Permalink to “Shrinking and Overflow”">​</a></h2><p>When a lowered capacity leaves occupancy beyond the boundary, the outcome is decided by <code>unlock.overflow_policy</code>. The key itself is documented in the <code>unlock</code> section of <a href="./configuration.html">Configuration</a>.</p><h3 id="the-four-overflow-policy-values" tabindex="-1">The Four overflow_policy Values <a class="header-anchor" href="#the-four-overflow-policy-values" aria-label="Permalink to “The Four overflow_policy Values”">​</a></h3><table tabindex="0"><thead><tr><th>Value</th><th>Behaviour</th></tr></thead><tbody><tr><td><code>lock_readonly</code></td><td>Entries beyond the capacity boundary become read-only: withdrawable, not depositable, released as soon as they are emptied. Recommended.</td></tr><tr><td><code>compact</code></td><td>Overflowing entries roll forward into free slots. Entries are already stored in a gap-free compact list, so &quot;roll forward&quot; is the list&#39;s natural state; whatever still does not fit degrades to <code>lock_readonly</code>.</td></tr><tr><td><code>return_inventory</code></td><td>Tries to hand overflowing entries back to the player&#39;s inventory; whatever does not fit degrades to <code>lock_readonly</code>. Nothing is returned while the player is offline, entries are simply locked.</td></tr><tr><td><code>reject_change</code></td><td>Refuses the shrink outright.</td></tr></tbody></table><p>All four policies are zero-loss. There is deliberately <strong>no</strong> <code>drop</code> or <code>delete</code>: irreversible data loss must never be triggered implicitly by adjusting a config value.</p><p>Overflow state is not persisted. It is derived from capacity versus occupancy and recomputed whenever capacity changes — login, reload, permission change, command grant — so a stored flag can never drift out of sync with the facts.</p><h2 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to “Related Pages”">​</a></h2><ul><li><a href="./configuration.html">Configuration</a>: the remaining <code>config.yml</code> sections such as <code>unlock</code>, <code>behavior</code> and <code>persistence</code>.</li><li><a href="./gui.html">GUI and Display</a>: how <code>gui.storage_rows</code> decides the slots per page.</li><li><a href="./unlock-costs.html">Unlock Costs</a>: pricing and the purchase flow behind <code>purchasedSlots</code>.</li><li><a href="./commands.html">Commands and Permissions</a>: <code>/estorage slot</code>, <code>/estorage stacklimit</code> and the permission tiers.</li><li><a href="./api.html">API and Integration</a>: how <code>StorageCapacity</code> fields map onto configuration keys.</li></ul>`,49)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};